import React from "react";
import './Header.css';

function Header() {
    return (
        <>
            <h2>Portfolio</h2>
            <nav>
                <a href="#">Home</a>
                <a href="#">About</a>
                <a href="#">Blog</a>
                <a href="#">Portefolio</a>
                <a href="#">Contact</a>
                <div class="animation start-home"></div>
            </nav>
        </>
    )
}
